import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify top features by effect size (mean_y1-mean_y0)
    effects = []
    for i, fid in enumerate(feats.ids):
        # Calculate mean difference for this feature
        y0_mean = np.mean(feats.x[feats.y==0, i])
        y1_mean = np.mean(feats.x[feats.y==1, i])
        effect = abs(y1_mean - y0_mean)
        effects.append((effect, fid))

    # Sort by effect size and take top 10
    effects.sort(reverse=True)
    top_features = [fid for _, fid in effects[:10]]

    # Check for strong correlations among top features
    corr_matrix = np.corrcoef(feats.x[:, [feats.column(fid) for fid in top_features]].T)

    # Find highly correlated pairs (|r| >= 0.6)
    correlated_pairs = []
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            if abs(corr_matrix[i,j]) >= 0.6:
                correlated_pairs.append((top_features[i], top_features[j]))

    # If we have correlated pairs, use the first feature as driver
    if correlated_pairs:
        # Use first feature from first correlated pair as driver
        driver = correlated_pairs[0][0]
        # Use all features in the correlation group
        module_features = set()
        for a, b in correlated_pairs:
            module_features.add(a)
            module_features.add(b)
        module_features = list(module_features)

        # Return simple design with driver and module
        return Design(
            drivers=(driver,),
            columns=tuple(module_features),
            products=(),
            loadings={fid: 1.0/len(module_features) for fid in module_features}
        )

    # No strong correlations found, just return top feature
    if top_features:
        return Design(
            drivers=(top_features[0],),
            columns=(top_features[0],),
            products=(),
            loadings={top_features[0]: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

